import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trash2, Plus, Play, Clock, Calendar, Download, 
  ShieldCheck, Globe, Home, BookOpen, ChevronRight, Settings2, Users, RefreshCw
} from 'lucide-react';

// --- HELPER FUNCTIONS ---
const formatTime = (timeStr) => {
  if (!timeStr) return "";
  const [h, m] = timeStr.split(':').map(Number);
  const suffix = h >= 12 ? 'PM' : 'AM';
  const displayH = h % 12 || 12;
  return `${displayH}:${String(m).padStart(2, '0')} ${suffix}`;
};

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const totalH = h + hours;
  return `${String(totalH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ 
  dept, 
  onUpdate, 
  onGenerate, 
  onDeleteDept, // Function to delete the entire department card and its data
  onClearSchedule, // Function to free the block combinations from the global schedule
  globalSchedule = [], 
  allDepartments = [] 
}) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [localPreview, setLocalPreview] = useState([]);
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // Sync local preview: If global schedule is cleared for this dept, clear the local view too
  useEffect(() => {
    const hasActiveSchedule = globalSchedule.some(s => s.dept_code === deptCode);
    if (!hasActiveSchedule) setLocalPreview([]);
  }, [globalSchedule, deptCode]);

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");
  const [roomType, setRoomType] = useState("Department");

  const globalProctorPool = useMemo(() => allDepartments.flatMap(d => d.proctors), [allDepartments]);
  const globalRoomPool = useMemo(() => allDepartments.flatMap(d => d.rooms), [allDepartments]);

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const handleGenerateClick = () => {
    const yearSubs = subjects[selectedYear] || [];
    if (yearSubs.length === 0) return alert("No subjects found!");
    if (examDays === 0 || sectionCount === 0) return alert("Complete configuration first!");
    if (examDates.some(d => !d)) return alert("Fill all dates!");

    const shuffled = [...yearSubs].sort(() => Math.random() - 0.5);
    const dailySubs = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubs[i % examDays].push(s));

    const finalGeneratedData = [];
    const previewData = [];

    for (let d = 0; d < examDays; d++) {
      const dayDate = examDates[d];
      const daySubjects = dailySubs[d];
      const duration = daySubjects.length;
      const endTime = addHours(startTime, duration);

      const isRoomFree = (rNum) => !globalSchedule.some(gs => gs.room === rNum && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time));
      const localRooms = rooms.filter(r => isRoomFree(r.number));
      const otherRooms = globalRoomPool.filter(r => !rooms.find(dr => dr.number === r.number) && isRoomFree(r.number));
      let availableRooms = roomSource === "Department" ? [...localRooms, ...otherRooms] : [...otherRooms, ...localRooms];
      availableRooms.sort((a,b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

      let dayUsedProctors = [];

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;
        const selectedRoom = availableRooms[s];
        if (!selectedRoom) return alert(`Room depletion on Day ${d+1}`);

        const checkProctor = (pool) => pool.find(p => 
            dayDate >= p.dayStart && dayDate <= p.dayEnd &&
            startTime >= p.timeStart && endTime <= p.timeEnd &&
            !dayUsedProctors.includes(p.name) &&
            !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time))
        );

        let selectedProctor = checkProctor(proctorSource === "Department" ? proctors : globalProctorPool);
        if (!selectedProctor && proctorSource === "Department") selectedProctor = checkProctor(globalProctorPool);
        if (!selectedProctor) return alert(`Staff depletion on Day ${d+1}`);

        dayUsedProctors.push(selectedProctor.name);

        const subjectSlots = daySubjects.map((sub, idx) => ({
            code: sub.code,
            name: sub.name,
            slot: `${formatTime(addHours(startTime, idx))} - ${formatTime(addHours(startTime, idx + 1))}`
        }));

        previewData.push({
          day: d + 1, section: sectionID, date: dayDate,
          time: `${formatTime(startTime)} - ${formatTime(endTime)}`,
          room: selectedRoom.number, proctor: selectedProctor.name,
          subs: subjectSlots
        });

        daySubjects.forEach((sub, idx) => {
          finalGeneratedData.push({
            subject_code: sub.code, subject_name: sub.name, section: sectionID,
            year_level: selectedYear, dept_code: deptCode, exam_date: dayDate,
            start_time: addHours(startTime, idx), end_time: addHours(startTime, idx + 1),
            room: selectedRoom.number, proctor: selectedProctor.name
          });
        });
      }
    }

    setLocalPreview(previewData);
    onGenerate(finalGeneratedData, examDates);
    setActiveTab("preview");
  };

  return (
    <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden mb-16 transition-all hover:shadow-blue-500/5">

      {/* HEADER SECTION */}
      <div className="bg-slate-900 p-10 text-white flex justify-between items-center relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-600 via-emerald-500 to-amber-500"></div>
        <div className="relative z-10">
          <div className="flex items-center gap-4">
            <h2 className="text-4xl font-black uppercase italic tracking-tighter leading-none">{deptName}</h2>
            {/* ENHANCEMENT: DELETE DEPT CARD BUTTON */}
            <button 
              onClick={() => onDeleteDept(deptId, deptCode)}
              className="bg-rose-500/20 hover:bg-rose-500 text-rose-500 hover:text-white p-2 rounded-xl transition-all"
              title="Delete Entire Department and Wipe Data"
            >
              <Trash2 size={20} />
            </button>
          </div>
          <p className="text-blue-400 text-[10px] font-black uppercase tracking-[0.4em] mt-3 flex items-center gap-2">
            <Settings2 size={12}/> Departmental Workspace Engine
          </p>
        </div>
        <div className="flex gap-4 relative z-10">
            <div className="bg-white/5 backdrop-blur-md px-6 py-3 rounded-[1.5rem] border border-white/10 text-center min-w-[80px]">
                <span className="block text-[8px] font-black text-blue-400 uppercase tracking-widest mb-1">Staff</span>
                <span className="text-2xl font-black">{proctors.length}</span>
            </div>
            <div className="bg-white/5 backdrop-blur-md px-6 py-3 rounded-[1.5rem] border border-white/10 text-center min-w-[80px]">
                <span className="block text-[8px] font-black text-emerald-400 uppercase tracking-widest mb-1">Rooms</span>
                <span className="text-2xl font-black">{rooms.length}</span>
            </div>
        </div>
      </div>

      {/* NAVIGATION TABS */}
      <div className="flex bg-slate-50/50 p-3 gap-2 border-b border-slate-100">
        {['subjects', 'proctors', 'rooms', 'generate', 'preview'].map(t => (
          <button 
            key={t} 
            onClick={() => setActiveTab(t)} 
            className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] rounded-2xl transition-all duration-300 ${
              activeTab === t 
              ? 'bg-white shadow-xl text-blue-600 scale-[1.02] border border-slate-100' 
              : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'
            }`}
          >
            {t}
          </button>
        ))}
      </div>

      <div className="p-12">
        {/* SUBJECTS TAB */}
        {activeTab === 'subjects' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-2">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 shadow-inner">
              <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-400 uppercase ml-2">Year Level</label>
                  <select className="w-full p-4 rounded-2xl text-xs font-black bg-white border-2 border-slate-100 outline-none focus:border-blue-500 transition-all appearance-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                      {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year Level {y}</option>)}
                  </select>
              </div>
              <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-400 uppercase ml-2">Subject Code</label>
                  <input id={`sC-${deptId}`} placeholder="e.g. CS101" className="w-full p-4 rounded-2xl text-xs font-black bg-white border-2 border-slate-100 outline-none focus:border-blue-500 transition-all" />
              </div>
              <div className="space-y-2 md:col-span-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase ml-2">Description</label>
                  <input id={`sN-${deptId}`} placeholder="Full Name" className="w-full p-4 rounded-2xl text-xs font-black bg-white border-2 border-slate-100 outline-none focus:border-blue-500 transition-all" />
              </div>
              <div className="pt-6">
                  <button onClick={() => {
                    const c = document.getElementById(`sC-${deptId}`).value;
                    const n = document.getElementById(`sN-${deptId}`).value;
                    if (c && n) {
                      onUpdate('subjects', { ...subjects, [selectedYear]: [...(subjects[selectedYear] || []), { code: c.toUpperCase(), name: n }] });
                      document.getElementById(`sC-${deptId}`).value = '';
                      document.getElementById(`sN-${deptId}`).value = '';
                    }
                  }} className="w-full h-full bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-blue-600/20 active:scale-95 transition-all flex items-center justify-center gap-2">
                      <Plus size={14}/> Add Item
                  </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto pr-4 custom-scrollbar">
              {subjects[selectedYear]?.map((s, i) => (
                <div key={i} className="group flex justify-between p-6 bg-white border-2 border-slate-50 rounded-3xl items-center transition-all hover:border-blue-100 hover:shadow-lg">
                  <div className="flex items-center gap-4">
                    <div className="bg-blue-50 p-3 rounded-xl text-blue-600 font-black text-xs">{s.code}</div>
                    <span className="text-slate-600 font-black text-xs uppercase tracking-tight">{s.name}</span>
                  </div>
                  <button onClick={() => onUpdate('subjects', { ...subjects, [selectedYear]: subjects[selectedYear].filter((_, idx) => idx !== i) })}>
                    <Trash2 size={18} className="text-slate-200 group-hover:text-rose-500 transition-colors" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* PROCTORS TAB */}
        {activeTab === 'proctors' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-2">
            <div className="bg-emerald-50/50 p-10 rounded-[3rem] border border-emerald-100 space-y-8 shadow-inner">
              <div className="flex flex-col md:flex-row gap-6">
                <div className="flex-1 space-y-2">
                  <label className="text-[9px] font-black text-emerald-600 uppercase ml-4">Full Legal Name</label>
                  <input value={pName} onChange={e => setPName(e.target.value)} placeholder="ENTER STAFF NAME" className="w-full p-5 rounded-3xl text-xs font-black border-2 border-emerald-100 outline-none focus:border-emerald-500 transition-all" />
                </div>
                <div className="md:pt-6">
                  <button onClick={() => {
                    if (pName && pDayStart && pDayEnd && pTimeStart && pTimeEnd) {
                      onUpdate('proctors', [...proctors, { id: Date.now(), name: pName.toUpperCase(), dayStart: pDayStart, dayEnd: pDayEnd, timeStart: pTimeStart, timeEnd: pTimeEnd }]);
                      setPName("");
                    }
                  }} className="h-full px-12 bg-emerald-600 text-white rounded-3xl font-black text-[10px] uppercase shadow-lg shadow-emerald-600/20 active:scale-95 transition-all">
                    Register Staff
                  </button>
                </div>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">Start Date</label><input type="date" value={pDayStart} onChange={e => setPDayStart(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50 outline-none" /></div>
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">End Date</label><input type="date" value={pDayEnd} onChange={e => setPDayEnd(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50 outline-none" /></div>
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">Shift Start</label><input type="time" value={pTimeStart} onChange={e => setPTimeStart(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50 outline-none" /></div>
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">Shift End</label><input type="time" value={pTimeEnd} onChange={e => setPTimeEnd(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50 outline-none" /></div>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto pr-4 custom-scrollbar">
              {proctors.map(p => (
                <div key={p.id} className="p-6 border-2 border-slate-50 rounded-[2.5rem] flex justify-between items-center bg-white hover:border-emerald-100 hover:shadow-lg transition-all group">
                  <div>
                    <p className="font-black text-xs uppercase text-slate-800 flex items-center gap-2">
                        <Users size={14} className="text-emerald-500"/> {p.name}
                    </p>
                    <p className="text-[9px] text-slate-400 font-black uppercase tracking-tighter mt-1 italic">
                        {p.dayStart} / {p.dayEnd} • {formatTime(p.timeStart)} - {formatTime(p.timeEnd)}
                    </p>
                  </div>
                  <Trash2 size={18} className="text-slate-100 group-hover:text-rose-500 cursor-pointer transition-colors" onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))} />
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ROOMS TAB */}
        {activeTab === 'rooms' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-2">
            <div className="flex flex-col md:flex-row gap-4 bg-amber-50/50 p-8 rounded-[3rem] border border-amber-100 shadow-inner">
              <input value={roomNum} onChange={e => setRoomNum(e.target.value)} placeholder="ROOM NO. OR HALL NAME" className="flex-1 p-5 rounded-3xl text-xs font-black border-2 border-amber-50 outline-none focus:border-amber-500 transition-all" />
              <select value={roomType} onChange={e => setRoomType(e.target.value)} className="bg-white px-8 rounded-3xl font-black text-[10px] uppercase outline-none shadow-sm border-2 border-amber-50 appearance-none">
                <option value="Department">Internal Resource</option>
                <option value="Global">Global Pool</option>
              </select>
              <button onClick={() => { if (roomNum) { onUpdate('rooms', [...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type: roomType }]); setRoomNum(""); } }} className="bg-amber-600 text-white px-10 py-5 rounded-3xl font-black uppercase text-[10px] shadow-lg shadow-amber-600/20 active:scale-95 transition-all">
                Add Room
              </button>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
              {rooms.map(r => (
                <div key={r.id} className="p-8 bg-white border-2 border-slate-50 rounded-[3rem] text-center relative group shadow-sm hover:border-amber-200 transition-all">
                  <span className="font-black text-2xl text-slate-800 tracking-tighter">{r.number}</span>
                  <span className={`block text-[8px] font-black uppercase mt-2 tracking-widest ${r.type === 'Global' ? 'text-blue-500' : 'text-amber-500'}`}>{r.type} Source</span>
                  <button className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={16}/></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* GENERATE TAB */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3.5rem] p-12 text-white shadow-2xl relative overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="absolute top-0 right-0 w-96 h-96 bg-blue-600/10 rounded-full blur-[100px] -mr-32 -mt-32"></div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-16 relative z-10">
              <div className="space-y-10">
                <h4 className="flex items-center gap-3 text-blue-400 font-black text-[10px] uppercase tracking-[0.4em]">
                    <div className="w-10 h-1 bg-blue-400 rounded-full"/> Timeline Config
                </h4>

                <div className="space-y-6">
                    <div className="group">
                        <label className="text-[9px] font-black text-slate-500 uppercase ml-4 mb-2 block">Total Exam Days</label>
                        <input type="number" value={examDays || ''} onChange={e => handleExamDayChange(e.target.value)} placeholder="0" className="w-full bg-slate-800/50 p-6 rounded-[2rem] text-3xl font-black text-blue-400 border-2 border-slate-700 focus:border-blue-500 transition-all outline-none" />
                    </div>

                    <div className="space-y-3 max-h-48 overflow-y-auto pr-4 custom-scrollbar">
                        {examDates.map((d, i) => (
                          <div key={i} className="flex items-center bg-slate-800 p-4 rounded-2xl border border-slate-700 group hover:border-blue-500/50 transition-all">
                            <span className="text-blue-500 font-black text-[10px] w-14">DAY {String(i+1).padStart(2, '0')}</span>
                            <input type="date" value={d} onChange={e => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="w-full bg-transparent text-xs font-black outline-none text-white cursor-pointer" />
                          </div>
                        ))}
                    </div>

                    <div className="group">
                        <label className="text-[9px] font-black text-slate-500 uppercase ml-4 mb-2 block">Starting Window</label>
                        <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-slate-800/50 p-5 rounded-2xl font-black text-blue-400 border-2 border-slate-700 outline-none" />
                    </div>
                </div>
              </div>

              <div className="space-y-10 flex flex-col">
                <h4 className="flex items-center gap-3 text-emerald-400 font-black text-[10px] uppercase tracking-[0.4em]">
                    <div className="w-10 h-1 bg-emerald-400 rounded-full"/> Logic Parameters
                </h4>

                <div className="space-y-4 flex-1">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-[9px] font-black text-slate-500 uppercase ml-4">Target Year</label>
                            <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="w-full bg-slate-800/50 p-5 rounded-2xl font-black text-xs text-blue-400 border-2 border-slate-700 outline-none appearance-none">
                                {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year Level {y}</option>)}
                            </select>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[9px] font-black text-slate-500 uppercase ml-4">Total Sections</label>
                            <input type="number" value={sectionCount || ''} onChange={e => setSectionCount(parseInt(e.target.value) || 0)} placeholder="0" className="w-full bg-slate-800/50 p-5 rounded-2xl font-black text-emerald-400 border-2 border-slate-700 outline-none" />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-3 pt-4">
                        <button onClick={() => setProctorSource(proctorSource === "Department" ? "Global" : "Department")} className="bg-slate-800 hover:bg-slate-700 p-5 rounded-2xl text-[10px] font-black uppercase flex justify-between items-center border border-slate-700 transition-all group">
                            <span className="flex items-center gap-3">
                                {proctorSource === "Department" ? <Home size={16} className="text-blue-500"/> : <Globe size={16} className="text-blue-500"/>}
                                Staff Source: {proctorSource}
                            </span>
                            <ChevronRight size={14} className="text-slate-600 group-hover:text-blue-400"/>
                        </button>
                        <button onClick={() => setRoomSource(roomSource === "Department" ? "Global" : "Department")} className="bg-slate-800 hover:bg-slate-700 p-5 rounded-2xl text-[10px] font-black uppercase flex justify-between items-center border border-slate-700 transition-all group">
                             <span className="flex items-center gap-3">
                                {roomSource === "Department" ? <Home size={16} className="text-emerald-500"/> : <Globe size={16} className="text-emerald-500"/>}
                                Room Source: {roomSource}
                             </span>
                             <ChevronRight size={14} className="text-slate-600 group-hover:text-emerald-400"/>
                        </button>

                        {/* ENHANCEMENT: CLEAR SCHEDULE/FREE BLOCKS BUTTON */}
                        <button 
                          onClick={() => onClearSchedule(deptCode)}
                          className="w-full bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/30 p-5 rounded-2xl text-[10px] font-black uppercase flex justify-between items-center text-rose-500 transition-all group mt-2"
                        >
                             <span className="flex items-center gap-3">
                                <RefreshCw size={16} /> Free Assigned Blocks
                             </span>
                             <span className="opacity-40 tracking-widest text-[8px]">RESET DRAFT</span>
                        </button>
                    </div>
                </div>

                <button onClick={handleGenerateClick} className="w-full bg-blue-600 py-10 rounded-[3rem] font-black uppercase tracking-[0.4em] text-xl shadow-[0_20px_50px_rgba(37,99,235,0.3)] hover:bg-blue-500 hover:-translate-y-1 active:translate-y-0 transition-all flex items-center justify-center gap-4 group">
                  <Play size={32} fill="currentColor" className="group-hover:scale-110 transition-transform"/> Start Calculation
                </button>
              </div>
            </div>
          </div>
        )}

        {/* PREVIEW TAB */}
        {activeTab === 'preview' && (
          <div className="space-y-10 animate-in fade-in duration-500">
            <div className="flex justify-between items-end border-b-2 border-slate-100 pb-8 px-4">
              <div>
                <h3 className="text-4xl font-black uppercase text-slate-900 tracking-tighter">Draft <span className="text-blue-600">Timeline</span></h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Generated Batch: Year {selectedYear}</p>
              </div>
              <div className="flex gap-4">
                {/* ENHANCEMENT: QUICK WIPE BUTTON IN PREVIEW */}
                <button 
                  onClick={() => onClearSchedule(deptCode)}
                  className="flex items-center gap-3 bg-white border-2 border-rose-100 text-rose-500 px-8 py-4 rounded-[1.5rem] font-black text-[10px] uppercase hover:bg-rose-50 transition-all active:scale-95"
                >
                  <Trash2 size={18} /> Wipe Schedule
                </button>
                <button onClick={() => {
                  if (localPreview.length === 0) return alert("Generate first!");
                  const headers = "Day,Section,Date,Window,Room,Proctor,Subject Breakdown\n";
                  const rows = localPreview.map(row => `${row.day},${row.section},${row.date},"${row.time}",${row.room},${row.proctor},"${row.subs.map(s => `${s.code} (${s.slot})`).join(' | ')}"`).join("\n");
                  const blob = new Blob([headers + rows], { type: 'text/csv' });
                  const url = URL.createObjectURL(blob);
                  const link = document.createElement('a');
                  link.href = url;
                  link.download = `${deptCode}_Year${selectedYear}.csv`;
                  link.click();
                }} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-4 rounded-[1.5rem] font-black text-[10px] uppercase shadow-2xl hover:bg-slate-800 transition-all active:scale-95">
                  <Download size={18} /> Export CSV Report
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-10">
                {localPreview.length > 0 ? localPreview.map((row, i) => (
                    <div key={i} className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden flex flex-col md:flex-row hover:border-blue-300 transition-all hover:shadow-2xl group">
                        {/* Section Sidebar */}
                        <div className="bg-slate-900 p-10 md:w-80 flex flex-col justify-between text-white border-r-8 border-blue-600">
                            <div>
                                <span className="text-blue-400 font-black text-[10px] uppercase tracking-[0.3em]">Block Identification</span>
                                <h5 className="text-5xl font-black tracking-tighter mt-2">{row.section}</h5>
                            </div>
                            <div className="mt-8 space-y-4">
                                <div className="flex items-center gap-3 text-[11px] font-black uppercase">
                                    <Calendar size={16} className="text-blue-400"/> {row.date}
                                </div>
                                <div className="flex items-center gap-3 text-[11px] font-black uppercase">
                                    <Clock size={16} className="text-blue-400"/> {row.time}
                                </div>
                            </div>
                            <div className="mt-10 pt-8 border-t border-white/10 space-y-3">
                                <div className="bg-blue-600 px-4 py-2 rounded-xl text-[10px] font-black flex justify-between items-center">
                                    <span>ROOM</span>
                                    <span>{row.room}</span>
                                </div>
                                <div className="bg-white/10 px-4 py-2 rounded-xl text-[10px] font-black flex justify-between items-center">
                                    <span>STAFF</span>
                                    <span className="truncate ml-2">{row.proctor}</span>
                                </div>
                            </div>
                        </div>

                        {/* Subject Details */}
                        <div className="flex-1 p-10 bg-slate-50/30">
                            <div className="flex items-center justify-between mb-8">
                                <div className="flex items-center gap-3">
                                    <BookOpen size={20} className="text-blue-600" />
                                    <span className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">Chronological Subjects</span>
                                </div>
                                <span className="text-[10px] font-black bg-blue-100 text-blue-700 px-3 py-1 rounded-full uppercase">Day {row.day}</span>
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                {row.subs.map((s, idx) => (
                                    <div key={idx} className="bg-white p-6 rounded-3xl border-2 border-white shadow-sm group-hover:border-blue-100 transition-all flex flex-col justify-between hover:shadow-md">
                                        <div className="flex justify-between items-start">
                                            <span className="text-sm font-black text-blue-600">{s.code}</span>
                                            <span className="text-[9px] font-black text-slate-400 uppercase italic tracking-tighter">{s.slot}</span>
                                        </div>
                                        <p className="text-[11px] font-black text-slate-800 uppercase mt-4 leading-snug">{s.name}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-32 bg-slate-50 rounded-[4rem] border-4 border-dashed border-slate-100">
                        <div className="bg-white w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 shadow-xl text-slate-200">
                            <Play size={32} fill="currentColor"/>
                        </div>
                        <p className="text-slate-300 font-black uppercase tracking-[0.4em] text-xs">Awaiting Execution Profile</p>
                    </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
